    27	/** Calcula o resumo da compra. É a única fonte dos valores, tanto do resumo quanto do pedido registrado. */
    28	@Service
    29	public class CheckoutService {
    30	
    31	    private static final BigDecimal COUPON_CAP_RATE = new BigDecimal("0.30");
    32	
    33	    private final ProductRepository products;
    34	    private final OrderRepository orders;
    35	    private final Map<String, ClubTier> clubTiers;
    36	    private final Map<String, ShippingOption> shippingOptions;
    37	    private final Map<String, Coupon> coupons;
    38	    private final Map<String, PaymentMethod> paymentMethods;
    39	
    40	    public CheckoutService(ProductRepository products, OrderRepository orders, List<ClubTier> clubTiers,
    41	                           List<ShippingOption> shippingOptions, List<Coupon> coupons,
    42	                           List<PaymentMethod> paymentMethods) {
    43	        this.products = products;
    44	        this.orders = orders;
    45	        this.clubTiers = Coded.index(clubTiers);
    46	        this.shippingOptions = Coded.index(shippingOptions);
    47	        this.coupons = Coded.index(coupons);
    48	        this.paymentMethods = Coded.index(paymentMethods);
    49	    }
    50	
    51	    public Summary calculate(CheckoutRequest request) {
    52	        validateShape(request);
    53	        List<CartLine> lines = resolveLines(request);
    54	
    55	        ClubTier tier = clubTiers.get(request.clubTier());
    56	        if (tier == null) {
    57	            throw DomainException.unprocessable("INVALID_CLUB_TIER");
    58	        }
    59	        Region region = Region.parse(request.region());
    60	        if (region == null) {
    61	            throw DomainException.unprocessable("INVALID_REGION");
    62	        }
    63	        if (request.zipCode() == null || !request.zipCode().matches("\\d{8}")) {
    64	            throw DomainException.unprocessable("INVALID_ZIP_CODE");
    65	        }
    66	        ShippingOption shipping = shippingOptions.get(request.shippingMethod());
    67	        if (shipping == null) {
    68	            throw DomainException.unprocessable("INVALID_SHIPPING_METHOD");
    69	        }
    70	
    71	        BigDecimal subtotal = Money.round(lines.stream().map(CartLine::total).reduce(BigDecimal.ZERO, BigDecimal::add));
    72	        BigDecimal weightKg = lines.stream().map(CartLine::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
    73	        ShippingQuote quote = shipping.quote(new ShippingRequest(request.zipCode(), region, weightKg));
    74	        BigDecimal shippingCost = tier.freeShipping(shipping) ? Money.ZERO : quote.cost();
    75	
    76	        BigDecimal couponDiscount = couponDiscount(request, lines, subtotal, shipping, shippingCost);
    77	        BigDecimal insurance = region.insuranceFor(subtotal);
    78	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
    79	
    80	        int installments = request.installments() == null ? 1 : request.installments();
    81	        PaymentMethod payment = paymentMethods.get(request.paymentMethod());
    82	        if (payment == null) {
    83	            throw DomainException.unprocessable("INVALID_PAYMENT_METHOD");
    84	        }
    85	        if (!payment.allowsInstallments(installments)) {
    86	            throw DomainException.unprocessable("INVALID_INSTALLMENTS");
    87	        }
    88	        if (!payment.availableFor(orderTotal)) {
    89	            throw DomainException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
    90	        }
    91	        var charge = payment.charge(
    92	                new PaymentMethod.PaymentContext(orderTotal, installments, request.coupon() != null));
    93	
    94	        return new Summary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
    95	                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), installments,
    96	                charge.installmentAmount(), tier.nextPurchaseCredit(subtotal), tier.gift(subtotal));
    97	    }
    98	
    99	    private BigDecimal couponDiscount(CheckoutRequest request, List<CartLine> lines, BigDecimal subtotal,
   100	                                      ShippingOption shipping, BigDecimal shippingCost) {
   101	        if (request.coupon() == null) {
   102	            return Money.ZERO;
   103	        }
   104	        Coupon coupon = coupons.get(request.coupon());
   105	        if (coupon == null) {
   106	            throw DomainException.unprocessable("INVALID_COUPON");
   107	        }
   108	        String cpf = request.customer().cpf();
   109	        BigDecimal discount = coupon.discount(new CouponContext(lines, subtotal, shipping, shippingCost,
   110	                () -> !orders.hasPurchase(cpf)));
   111	        BigDecimal cap = Money.percent(subtotal, COUPON_CAP_RATE);
   112	        return discount.compareTo(cap) > 0 ? cap : discount;
   113	    }
   114	
   115	    private void validateShape(CheckoutRequest request) {
   116	        boolean valid = request.customer() != null
   117	                && notBlank(request.customer().cpf())
   118	                && notBlank(request.customer().email())
   119	                && request.items() != null
   120	                && !request.items().isEmpty();
   121	        if (valid) {
   122	            Set<String> seen = new HashSet<>();
   123	            for (var item : request.items()) {
   124	                if (item == null || !notBlank(item.sku()) || item.quantity() == null || item.quantity() <= 0
   125	                        || !seen.add(item.sku())) {
   126	                    valid = false;
   127	                    break;
   128	                }
   129	            }
   130	        }
   131	        if (!valid) {
   132	            throw DomainException.unprocessable("INVALID_ORDER");
   133	        }
   134	    }
   135	
   136	    private List<CartLine> resolveLines(CheckoutRequest request) {
   137	        List<CartLine> lines = new ArrayList<>();
   138	        for (var item : request.items()) {
   139	            Product product = products.find(item.sku())
   140	                    .orElseThrow(() -> DomainException.unprocessable("UNKNOWN_PRODUCT"));
   141	            lines.add(new CartLine(product, item.quantity()));
   142	        }
   143	        if (lines.stream().anyMatch(line -> line.product().discontinued())) {
   144	            throw DomainException.unprocessable("PRODUCT_DISCONTINUED");
   145	        }
   146	        if (lines.stream().anyMatch(line -> line.product().stock() < line.quantity())) {
   147	            throw DomainException.unprocessable("INSUFFICIENT_STOCK");
   148	        }
   149	        return lines;
   150	    }
   151	
   152	    private static boolean notBlank(String value) {
   153	        return value != null && !value.isBlank();
   154	    }
   155	}
