    16	
    17	    public NotificationRepository(JdbcClient jdbc) {
    18	        this.jdbc = jdbc;
    19	    }
    20	
    21	    public void create(String cpf, NotificationType type, String orderId) {
    22	        jdbc.sql("INSERT INTO notifications (id, cpf, type, order_id, status) VALUES (?, ?, ?, ?, 'NEW')")
    23	                .param(UUID.randomUUID().toString()).param(cpf).param(type.name()).param(orderId)
    24	                .update();
    25	    }
    26	
    27	    public List<Notification> listByCustomer(String cpf) {
    28	        return jdbc.sql("SELECT " + COLUMNS + " FROM notifications WHERE cpf = ? ORDER BY seq")
    29	                .param(cpf)
    30	                .query(this::map)
    31	                .list();
    32	    }
    33	
    34	    public Optional<Notification> find(String id) {
    35	        return jdbc.sql("SELECT " + COLUMNS + " FROM notifications WHERE id = ?")
    36	                .param(id)
    37	                .query(this::map)
    38	                .optional();
    39	    }
    40	
    41	    public void markRead(String id) {
    42	        jdbc.sql("UPDATE notifications SET status = 'READ' WHERE id = ?").param(id).update();
    43	    }
